class MountainPeaksTest{public static void main(String[]a){double r=.14,aspect=2;int peaks=0;double last=MountainPeaks.profile(-r*aspect,0,r,aspect,.5,71),current=last;for(int i=1;i<=2000;i++){double next=MountainPeaks.profile((i/1000.-1)*r*aspect,0,r,aspect,.5,71);if(current>last&&current>next)peaks++;last=current;current=next;}double summit=MountainPeaks.profile(0,0,r,aspect,.5,71),shoulder=MountainPeaks.profile(r*.01,0,r,aspect,.5,71);if(peaks<3||summit-shoulder<.008||MountainPeaks.profile(r*aspect*1.1,0,r,aspect,.5,71)!=0)throw new AssertionError("Peaks are broad plateaus or do not blend out: "+peaks);System.out.println("PASS: three distinct summits, sharp central peak and smooth outer foothill envelope");}}
